//! Support items for code generated by `#[derive(GoYaml)]` and `#[derive(GoMapstructure)]`.
//! Not public API.

pub use core::{
    clone::Clone,
    option::Option::{self, None, Some},
    result::Result::{self, Ok},
};
pub use std::{string::String, sync::OnceLock};

pub use pbs_gojson::GoKind;

pub use crate::{
    mapstructure::{DecodeError as MsError, Decoder as MsDecoder, MsDecode, MsField, MsStruct},
    value::Value,
    yaml::{
        Decoder as YamlDecoder, FieldDesc, NodeId, Scalar, StructInfo, UnmarshalError as YamlError,
        YamlDecode, YamlInline, YamlInlineMap, YamlStruct,
    },
};
